INSERT INTO app_private.coaching_schemes (scheme_key,model_key,name_i18n,result_i18n,style,estimated_minutes,topic_tags,step_keys,required_custom_plan,published) VALUES
 ('woop_money_habit_v1','woop_v1','{"en":"Money Habits · WOOP","ru":"Денежные привычки · WOOP","es":"Hábitos de dinero · WOOP"}'::jsonb,'{"en":"One self-chosen everyday money habit and a specific if–then plan; no financial advice.","ru":"Одна выбранная денежная привычка и конкретный план «если — то», без финансовых рекомендаций.","es":"Un hábito financiero elegido y un plan «si–entonces», sin asesoría financiera."}'::jsonb,'quick',10,ARRAY['money','budget','habits']::text[],ARRAY['wish','outcome','obstacle','plan']::text[],true,true),
 ('woop_wellbeing_routine_v1','woop_v1','{"en":"Healthy Routine · WOOP","ru":"Здоровая привычка · WOOP","es":"Rutina saludable · WOOP"}'::jsonb,'{"en":"A feasible non-medical self-care routine and your own if–then step.","ru":"Посильная привычка заботы о себе и собственный план «если — то», без медицинских советов.","es":"Un hábito de autocuidado no médico y tu propio plan «si–entonces»."}'::jsonb,'quick',10,ARRAY['wellbeing','stress','sleep','habits']::text[],ARRAY['wish','outcome','obstacle','plan']::text[],true,true),
 ('oskar_wellbeing_resources_v1','oskar_v1','{"en":"Wellbeing Resources · OSKAR","ru":"Ресурсы самочувствия · OSKAR","es":"Recursos de bienestar · OSKAR"}'::jsonb,'{"en":"Notice existing support and a modest daily-life improvement, without treating symptoms.","ru":"Заметить доступные ресурсы и небольшой повседневный шаг без лечения симптомов.","es":"Reconocer apoyos existentes y una pequeña mejora cotidiana, sin tratar síntomas."}'::jsonb,'reflective',20,ARRAY['wellbeing','stress','sleep','confidence']::text[],ARRAY['outcome','scaling','knowhow','affirm','review']::text[],false,true),
 ('solution_relationship_dialogue_v1','solution_focus_v1','{"en":"Relationship Clarity · Solution Focus","ru":"Ясность в отношениях · Фокус на решении","es":"Claridad en pareja · Enfoque en soluciones"}'::jsonb,'{"en":"A kinder conversation and one change within your control, without controlling a partner.","ru":"Более ясный разговор и один ваш собственный шаг, без попытки управлять партнёром.","es":"Un diálogo más claro y un paso bajo tu control, sin controlar a tu pareja."}'::jsonb,'quick',12,ARRAY['relationships','conflict','communication']::text[],ARRAY['preferred','scale','step']::text[],false,true),
 ('clear_intimacy_dialogue_v1','clear_v1','{"en":"Intimate Dialogue · CLEAR","ru":"Интимный диалог · CLEAR","es":"Diálogo íntimo · CLEAR"}'::jsonb,'{"en":"Choose words for a pressure-free conversation about closeness, consent and boundaries.","ru":"Подобрать слова для разговора о близости, согласии и границах без давления.","es":"Encontrar palabras para hablar de intimidad, consentimiento y límites sin presión."}'::jsonb,'reflective',25,ARRAY['sexuality','intimacy','consent','boundaries','relationships']::text[],ARRAY['contract','listen','explore','action','review']::text[],false,true),
 ('tantric_consent_quick_v1','tantric_intimacy_v1','{"en":"Consent & Boundaries · Tantra","ru":"Согласие и границы · Тантра","es":"Consentimiento y límites · Tantra"}'::jsonb,'{"en":"Name one boundary and a respectful way to ask or say no; no physical exercise.","ru":"Назвать одну границу и уважительную формулировку просьбы или отказа; без телесных практик.","es":"Nombrar un límite y una petición o negativa respetuosa; sin ejercicios físicos."}'::jsonb,'quick',12,ARRAY['sexuality','intimacy','consent','boundaries','tantra']::text[],ARRAY['intention','boundaries','consent','dialogue','step']::text[],false,true),
 ('tantric_desire_presence_v1','tantric_intimacy_v1','{"en":"Desire & Inner Comfort · Tantra","ru":"Желание и телесный комфорт · Тантра","es":"Deseo y comodidad interior · Tantra"}'::jsonb,'{"en":"Explore your own wishes, comfort and pace without touch or pressure.","ru":"Исследовать собственные желания, комфорт и темп без прикосновений и давления.","es":"Explorar deseos, comodidad y ritmo propios sin contacto ni presión."}'::jsonb,'reflective',15,ARRAY['sexuality','intimacy','desire','tantra']::text[],ARRAY['intention','presence','desire','boundaries','review']::text[],false,true),
 ('oskar_money_confidence_v1','oskar_v1','{"en":"Money Confidence · OSKAR","ru":"Уверенность в деньгах · OSKAR","es":"Confianza con el dinero · OSKAR"}'::jsonb,'{"en":"Reflect on money-related confidence, available resources and a small choice, not an investment plan.","ru":"Разобраться в уверенности относительно денег, ресурсах и небольшом выборе — не инвестиционный план.","es":"Reflexionar sobre confianza, recursos y una elección pequeña, no inversión."}'::jsonb,'reflective',20,ARRAY['money','budget','confidence']::text[],ARRAY['outcome','scaling','knowhow','affirm','review']::text[],false,true)
